<?php
putenv('BRAINPRESS_DSN=sqlite::memory:');require dirname(__DIR__).'/src/bootstrap.php';
function urlCheck(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
$_SERVER['HTTP_HOST']='127.0.0.1:8081';$_SERVER['HTTPS']='off';urlCheck(absoluteSiteUrl('/?page_slug=home')==='http://127.0.0.1:8081/?page_slug=home','Automatic site address preserves the local port');$_SERVER['HTTPS']='on';$_SERVER['HTTP_HOST']='brainpress.example';urlCheck(siteUrl()==='https://brainpress.example','HTTPS request uses an HTTPS origin');saveSetting('site_url',normalizeSiteUrl('https://Example.com/'));urlCheck(absoluteSiteUrl('/uploads/test.png')==='https://example.com/uploads/test.png','Configured public origin overrides the request host');urlCheck(absoluteSiteUrl('https://images.example/test.png')==='https://images.example/test.png','External image addresses remain unchanged');urlCheck(normalizeSiteUrl('http://[::1]:8081/')==='http://[::1]:8081','IPv6 development origins are supported');
foreach(['javascript:alert(1)','//example.com','https://example.com/subdirectory','https://example.com?x=1','https://user:password@example.com','https://example.com/#fragment',"https://exa\nmple.com"] as $input){try{normalizeSiteUrl($input);throw new RuntimeException('Accepted invalid site origin');}catch(InvalidArgumentException){echo "PASS Invalid site origin rejected\n";}}
saveSetting('site_url','');$_SERVER['HTTP_HOST']='bad.example/path';urlCheck(siteUrl()==='http://localhost','Malformed request hosts cannot contaminate copied addresses');
